 Check(app.SetEditorCameraPose({100,100,100},0,0),"editor camera outside volume");frame();Check(!gpu->GetFogDiagnostics().active,"Editor camera outside owned volume");app.SetEditorPlayMode(true);frame(8);Check(BoxVertices()==0,"Play hides new volume debug geometry even with Game View disabled");Check(app.GetLuaRuntime().HasCameraOwner(),"real PlayerStart camera is active");Check(app.GetCameraPosition().x<50,"Play follows gameplay camera instead of outside Editor camera");auto expected=EvaluatePostProcess(app.GetCameraPosition(),app.GetWorld(),PostProcessSettings{});Check(ApplicationTestAccess::PostProcess(app).activeVolumes==expected.activeVolumes,"Play evaluates actual viewport camera position");Check(expected.activeVolumes>0&&gpu->GetFogDiagnostics().active,"gameplay camera enters the authored local volume");
